import { Injectable, Logger } from '@nestjs/common';
import { mkdir, readFile, rm, writeFile } from 'fs/promises';
import { dirname, join, resolve, sep } from 'path';

export const FILE_STORAGE = Symbol('FileStorage');

/**
 * Binary storage for user files. Keys are generated by the server (never from user input).
 * LocalDiskStorage is for development/single-server; swap for an S3-compatible
 * implementation in production without touching callers.
 */
export interface FileStorage {
  save(key: string, data: Buffer): Promise<void>;
  read(key: string): Promise<Buffer>;
  delete(key: string): Promise<void>;
}

@Injectable()
export class LocalDiskStorage implements FileStorage {
  private readonly logger = new Logger(LocalDiskStorage.name);
  private readonly root = resolve(process.env.UPLOADS_DIR ?? join(process.cwd(), 'storage', 'uploads'));

  async save(key: string, data: Buffer): Promise<void> {
    const path = this.pathFor(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, data, { flag: 'wx' }); // never overwrite
  }

  read(key: string): Promise<Buffer> {
    return readFile(this.pathFor(key));
  }

  async delete(key: string): Promise<void> {
    await rm(this.pathFor(key), { force: true }).catch((err) =>
      this.logger.warn(`Could not delete ${key}: ${String(err)}`),
    );
  }

  /** Defense in depth: keys are server-generated, but never allow escaping the root. */
  private pathFor(key: string): string {
    const path = resolve(this.root, key);
    if (!path.startsWith(this.root + sep)) throw new Error('Invalid storage key');
    return path;
  }
}
